import { Link, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const isAdmin = user?.role === 'admin';

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const linkClass = ({ isActive }) =>
    `restaurant-nav-link ${isActive ? 'restaurant-nav-link-active' : ''}`;

  return (
    <nav className="restaurant-nav">
      <Link to="/" className="font-serif text-2xl font-semibold text-stone-950">
        Digi Meat Restaurant
      </Link>
      <div className="flex flex-wrap items-center justify-end gap-x-8 gap-y-3">
        {user ? (
          <>
            <NavLink to="/" className={linkClass}>
              Home
            </NavLink>
            {isAdmin ? (
              <>
                <NavLink to="/admin-dashboard" className={linkClass}>
                  Dashboard
                </NavLink>
                <NavLink to="/my-reservations" className={linkClass}>
                  Reservations
                </NavLink>
                <NavLink to="/tasks" className={linkClass}>
                  Tables
                </NavLink>
                <span className="restaurant-nav-link">Users</span>
                <span className="restaurant-nav-link">Restaurant Info</span>
              </>
            ) : (
              <>
                <NavLink to="/make-reservation" className={linkClass}>
                  Make Reservation
                </NavLink>
                <NavLink to="/my-reservations" className={linkClass}>
                  My Reservations
                </NavLink>
                <NavLink to="/profile" className={linkClass}>
                  Dashboard
                </NavLink>
              </>
            )}
            <button
              onClick={handleLogout}
              className="restaurant-nav-link"
            >
              Logout
            </button>
          </>
        ) : (
          <>
            <NavLink to="/" className={linkClass}>
              Home
            </NavLink>
            <NavLink to="/make-reservation" className={linkClass}>
              Make Reservation
            </NavLink>
            <NavLink to="/my-reservations" className={linkClass}>
              My Reservations
            </NavLink>
            <NavLink to="/login" className={linkClass}>
              Login
            </NavLink>
            <NavLink to="/register" className="restaurant-button h-[49px] px-6">
              Register
            </NavLink>
          </>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
